const entryOf = parts => {
  const entry = unflatten({ tokens: huffDecode(parts[2]), i: 0 });
  entry.body = b(parts[1]);
  for (let i = 3; i < parts.length; i += 2) (entry.globalInits ??= {})[parts[i]] = b(parts[i + 1]);
  return entry;
};

